-- Authenticated customer product services use the same admissions/rate/audit
-- ledger as owner APIs. No customer key or service-role bearer becomes a user.
BEGIN;
CREATE TABLE public.sandy_product_operation_contracts(operation text PRIMARY KEY, contract jsonb NOT NULL);
CREATE TABLE public.sandy_product_mutation_evidence(admission_id uuid PRIMARY KEY REFERENCES public.sandy_api_execution_admissions(id),before_state jsonb,after_state jsonb,evidence_sha256 text NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE public.sandy_product_results(admission_id uuid PRIMARY KEY REFERENCES public.sandy_api_execution_admissions(id),result jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),executed boolean);
CREATE TABLE public.sandy_product_support_cases(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),customer_id uuid NOT NULL REFERENCES public.email_customers(id),subject text NOT NULL,details text NOT NULL,category text NOT NULL CHECK(category IN ('account','billing','technical','privacy','other')),state text NOT NULL DEFAULT 'open' CHECK(state IN ('open','closed')),version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE public.sandy_product_support_comments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),case_id uuid NOT NULL REFERENCES public.sandy_product_support_cases(id),actor_id uuid NOT NULL,body text NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE public.sandy_product_notification_preferences(customer_id uuid PRIMARY KEY REFERENCES public.email_customers(id),email_enabled boolean NOT NULL DEFAULT false,whatsapp_enabled boolean NOT NULL DEFAULT false,file_alerts_enabled boolean NOT NULL DEFAULT true,updated_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE public.sandy_product_notification_quiet_hours(customer_id uuid PRIMARY KEY REFERENCES public.email_customers(id),enabled boolean NOT NULL DEFAULT false,timezone text NOT NULL DEFAULT 'UTC',start_minute integer NOT NULL DEFAULT 1320 CHECK(start_minute BETWEEN 0 AND 1439),end_minute integer NOT NULL DEFAULT 420 CHECK(end_minute BETWEEN 0 AND 1439),updated_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE public.sandy_product_notification_subscriptions(customer_id uuid NOT NULL REFERENCES public.email_customers(id),topic text NOT NULL CHECK(topic IN ('support','file_alerts','improvements')),enabled boolean NOT NULL DEFAULT true,updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(customer_id,topic));
CREATE TABLE public.sandy_product_notification_templates(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL UNIQUE,body_text text NOT NULL,version integer NOT NULL DEFAULT 1,deleted_at timestamptz,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE public.sandy_product_notification_inbox(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),customer_id uuid NOT NULL REFERENCES public.email_customers(id),topic text NOT NULL,event text NOT NULL,resource_id uuid NOT NULL,acknowledged_at timestamptz,created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE public.sandy_product_configuration_snapshots(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),admission_id uuid NOT NULL,provider_key text NOT NULL,before_row jsonb NOT NULL,after_row jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE public.sandy_product_graph_syncs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),actor_id uuid NOT NULL,next_url text NOT NULL,state text NOT NULL CHECK(state IN ('ready','dispatching','complete','unknown')),version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE public.sandy_product_whatsapp_media(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),customer_id uuid NOT NULL REFERENCES public.email_customers(id),provider_id text NOT NULL,filename text NOT NULL,content_type text NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE public.sandy_product_graph_drafts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),customer_id uuid NOT NULL REFERENCES public.email_customers(id),source_message_id uuid REFERENCES public.email_messages(id),provider_id text NOT NULL,recipient text NOT NULL,recipients jsonb NOT NULL DEFAULT '[]',state text NOT NULL CHECK(state IN ('draft','sending','submitted','sent','deleted','unknown','editing')),version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp());
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['sandy_product_operation_contracts','sandy_product_results','sandy_product_support_cases','sandy_product_support_comments','sandy_product_notification_preferences','sandy_product_configuration_snapshots','sandy_product_graph_drafts','sandy_product_notification_quiet_hours','sandy_product_notification_subscriptions','sandy_product_notification_templates','sandy_product_notification_inbox','sandy_product_graph_syncs','sandy_product_whatsapp_media','sandy_product_mutation_evidence'] LOOP
 EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('REVOKE ALL ON public.%I FROM PUBLIC,anon,authenticated,service_role',t); END LOOP; END $$;
-- Only the deliberately small schema vocabulary used by these fixed contracts is
-- accepted. This is not a general JSON Schema or caller-defined SQL engine.
CREATE FUNCTION public.sandy_product_input_valid(p_schema jsonb,p_value jsonb,p_depth integer DEFAULT 0) RETURNS boolean
LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog,pg_temp AS $$
DECLARE kind text; field record; required text; candidate jsonb;
BEGIN
 IF p_depth>8 OR p_schema IS NULL OR p_value IS NULL THEN RETURN false; END IF;
 IF p_schema ? 'const' THEN RETURN p_schema->'const'=p_value; END IF;
 IF p_schema ? 'enum' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p_schema->'enum') v WHERE v=p_value) THEN RETURN false; END IF;
 kind:=p_schema->>'type';
 IF kind='object' THEN
  IF jsonb_typeof(p_value)<>'object' OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_value) k WHERE NOT (p_schema->'properties') ? k) THEN RETURN false; END IF;
  FOR required IN SELECT jsonb_array_elements_text(coalesce(p_schema->'required','[]')) LOOP IF NOT p_value ? required THEN RETURN false; END IF; END LOOP;
  FOR field IN SELECT key,value FROM jsonb_each(p_value) LOOP IF NOT public.sandy_product_input_valid(p_schema->'properties'->field.key,field.value,p_depth+1) THEN RETURN false; END IF; END LOOP;
 ELSIF kind='array' THEN
  IF jsonb_typeof(p_value)<>'array' OR jsonb_array_length(p_value)<coalesce((p_schema->>'minItems')::integer,0) OR jsonb_array_length(p_value)>coalesce((p_schema->>'maxItems')::integer,100) THEN RETURN false;END IF;
  IF p_schema->>'uniqueItems'='true' AND (SELECT count(DISTINCT v) FROM jsonb_array_elements(p_value)v)<>jsonb_array_length(p_value) THEN RETURN false;END IF;
  FOR candidate IN SELECT value FROM jsonb_array_elements(p_value) LOOP IF NOT public.sandy_product_input_valid(p_schema->'items',candidate,p_depth+1) THEN RETURN false;END IF;END LOOP;
 ELSIF kind='string' THEN
  IF jsonb_typeof(p_value)<>'string' OR char_length(p_value#>>'{}')<coalesce((p_schema->>'minLength')::integer,0) OR char_length(p_value#>>'{}')>coalesce((p_schema->>'maxLength')::integer,100000) THEN RETURN false; END IF;
  IF p_schema ? 'pattern' AND (p_value#>>'{}') !~ (p_schema->>'pattern') THEN RETURN false; END IF;
  IF p_schema->>'format'='email' AND (p_value#>>'{}') !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' THEN RETURN false;END IF;
  IF p_schema->>'format'='uuid' AND (p_value#>>'{}') !~* '^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$' THEN RETURN false; END IF;
  IF p_schema->>'format'='date-time' THEN IF (p_value#>>'{}') !~* '^[0-9]{4}-[0-9]{2}-[0-9]{2}T.*(Z|[+-][0-9]{2}:[0-9]{2})$' THEN RETURN false; END IF; PERFORM (p_value#>>'{}')::timestamptz; END IF;
 ELSIF kind='boolean' THEN IF jsonb_typeof(p_value)<>'boolean' THEN RETURN false; END IF;
 ELSIF kind='integer' THEN
  IF jsonb_typeof(p_value)<>'number' OR (p_value#>>'{}') !~ '^-?[0-9]+$' OR (p_value#>>'{}')::numeric<coalesce((p_schema->>'minimum')::numeric,-2147483648) OR (p_value#>>'{}')::numeric>coalesce((p_schema->>'maximum')::numeric,2147483647) THEN RETURN false; END IF;
 ELSE RETURN false;
 END IF;
 RETURN true;
EXCEPTION WHEN data_exception THEN RETURN false;
END $$;
CREATE FUNCTION public.sandy_product_principal(p_operation text) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE actor uuid:=auth.uid(); tenant uuid; config jsonb; email text;
BEGIN
 IF actor IS NULL OR auth.role() IS DISTINCT FROM 'authenticated' THEN RETURN NULL; END IF;
 SELECT lower(u.email) INTO email FROM auth.users u WHERE u.id=actor AND u.email_confirmed_at IS NOT NULL;
 IF email IS NULL THEN RETURN NULL; END IF;
 SELECT contract INTO config FROM public.sandy_product_operation_contracts WHERE operation=p_operation;
 IF config IS NULL THEN RETURN NULL; END IF;
 IF config->>'authorization'='owner' THEN
  IF NOT public.sandy_api_current_owner(actor) THEN RETURN NULL; END IF;
 ELSIF config->>'authorization'='portal' THEN
  SELECT p.customer_id INTO tenant FROM public.sandy_memory_portal_accounts p JOIN public.email_customer_addresses a ON a.customer_id=p.customer_id AND a.is_primary AND a.normalized_email=email WHERE p.auth_user_id=actor AND p.revoked_at IS NULL;
  IF tenant IS NULL THEN RETURN NULL; END IF;
 END IF;
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',tenant);
END $$;
CREATE FUNCTION public.sandy_product_scope_sha(p_operation text,p_actor uuid,p_tenant uuid,p_channel text,p_contract_sha text) RETURNS text
LANGUAGE sql IMMUTABLE SET search_path=pg_catalog,pg_temp AS $$
 SELECT encode(extensions.digest('sandy_product_v1:'||p_actor::text||':'||coalesce(p_tenant::text,'owner')||':'||p_operation||':'||p_channel||':'||p_contract_sha,'sha256'),'hex')
$$;
CREATE FUNCTION public.sandy_product_admit(p_operation text,p_arguments jsonb,p_canonical_arguments text,p_request_id uuid,p_channel text DEFAULT 'api',p_approval_id uuid DEFAULT NULL) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE principal jsonb; config jsonb; registry public.sandy_operation_registry%ROWTYPE; prior public.sandy_api_execution_admissions%ROWTYPE; admission public.sandy_api_execution_admissions%ROWTYPE; input_hash text;scope_hash text;active_window timestamptz:=date_trunc('minute',clock_timestamp());requests integer;units integer;
BEGIN
 principal:=public.sandy_product_principal(p_operation); IF principal IS NULL THEN RETURN jsonb_build_object('ok',false,'error','product_identity_or_grant_required','http_status',403); END IF;
 SELECT contract INTO config FROM public.sandy_product_operation_contracts WHERE operation=p_operation;
 IF p_channel IS NULL OR p_channel NOT IN ('api','mcp') OR p_request_id IS NULL OR octet_length(p_canonical_arguments)>100000 OR p_canonical_arguments::jsonb IS DISTINCT FROM p_arguments OR NOT public.sandy_product_input_valid(config->'input_schema',p_arguments) THEN RETURN jsonb_build_object('ok',false,'error','invalid_product_arguments','http_status',400); END IF;
 IF (config->>'is_mutation')::boolean AND (p_arguments->>'idempotency_key')::uuid IS DISTINCT FROM p_request_id THEN RETURN jsonb_build_object('ok',false,'error','stable_idempotency_key_required','http_status',400); END IF;
 SELECT * INTO registry FROM public.sandy_operation_registry WHERE operation=p_operation FOR SHARE;
 IF registry.handler IS DISTINCT FROM 'sandy-product-service-api' OR registry.api_exposed IS DISTINCT FROM true OR (p_channel='mcp' AND registry.ai_exposed IS DISTINCT FROM true) OR registry.error_contract->>'contract_sha256' IS DISTINCT FROM config->>'contract_sha256' OR registry.error_contract->>'requires_approval' IS DISTINCT FROM ((config->>'authorization'='owner') AND ((config->>'is_mutation')::boolean OR(config->>'sensitive')::boolean))::text OR registry.error_contract->>'api_key_delegable' IS DISTINCT FROM 'false' OR registry.is_mutation IS DISTINCT FROM (config->>'is_mutation')::boolean OR registry.input_schema IS DISTINCT FROM config->'input_schema' OR registry.output_schema IS DISTINCT FROM config->'output_schema' OR registry.permission_scope IS DISTINCT FROM (CASE WHEN config->>'authorization'='owner' THEN 'system:' ELSE 'product:' END||CASE WHEN (config->>'is_mutation')::boolean THEN 'write' ELSE 'read' END) THEN RETURN jsonb_build_object('ok',false,'error','product_contract_not_enabled','http_status',403); END IF;
 IF (registry.is_mutation OR (config->>'sensitive')::boolean) AND NOT registry.verified THEN RETURN jsonb_build_object('ok',false,'error','operation_requires_live_verification','http_status',424); END IF;
 input_hash:=encode(extensions.digest(p_canonical_arguments,'sha256'),'hex');scope_hash:=public.sandy_product_scope_sha(p_operation,(principal->>'actor_id')::uuid,(principal->>'tenant_id')::uuid,p_channel,config->>'contract_sha256');
 IF config->>'authorization'='owner' THEN
  principal:=principal||public.sandy_api_admit_execution((principal->>'actor_id')::uuid,NULL,p_operation,input_hash,p_request_id,NULL,config->>'contract_sha256',scope_hash,CASE WHEN (config->>'consumes_provider_units')::boolean THEN 1 ELSE 0 END,p_approval_id);
  IF principal->>'reused'='true' THEN principal:=principal||jsonb_build_object('receipt',(SELECT result FROM public.sandy_product_results WHERE admission_id=(principal->>'admission_id')::uuid),'executed',(SELECT executed FROM public.sandy_product_results WHERE admission_id=(principal->>'admission_id')::uuid));END IF;RETURN principal;
 END IF;
 IF principal->>'tenant_id' IS NULL THEN RETURN jsonb_build_object('ok',false,'error','product_receipt_endpoint_required','http_status',400);END IF;
 IF p_approval_id IS NOT NULL THEN RETURN jsonb_build_object('ok',false,'error','owner_approval_not_customer_session','http_status',400); END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('sandy-product:'||(principal->>'actor_id')||':'||p_request_id::text,0));
 SELECT * INTO prior FROM public.sandy_api_execution_admissions WHERE actor_id=(principal->>'actor_id')::uuid AND request_id=p_request_id;
 IF FOUND THEN
  IF prior.operation<>p_operation OR prior.tenant_id IS DISTINCT FROM (principal->>'tenant_id')::uuid OR prior.input_sha256<>input_hash OR prior.contract_sha256<>config->>'contract_sha256' OR prior.scope_sha256<>scope_hash THEN RETURN jsonb_build_object('ok',false,'error','request_id_conflict','http_status',409); END IF;
  RETURN jsonb_build_object('ok',true,'reused',true,'admission_id',prior.id,'request_id',prior.request_id,'state',prior.state,'receipt',(SELECT result FROM public.sandy_product_results WHERE admission_id=prior.id),'executed',coalesce((SELECT executed FROM public.sandy_product_results WHERE admission_id=prior.id),CASE WHEN prior.state IN ('admitted','rejected') THEN false ELSE NULL END));
 END IF;
 INSERT INTO public.sandy_api_rate_windows(actor_id,bucket,window_start,requests,declared_units) VALUES((principal->>'actor_id')::uuid,'product:'||(principal->>'tenant_id'),active_window,0,0) ON CONFLICT DO NOTHING;
 SELECT w.requests,w.declared_units INTO requests,units FROM public.sandy_api_rate_windows w WHERE w.actor_id=(principal->>'actor_id')::uuid AND w.bucket='product:'||(principal->>'tenant_id') AND w.window_start=active_window FOR UPDATE;
 IF requests>=60 OR ((config->>'consumes_provider_units')::boolean AND units>=1) THEN RETURN jsonb_build_object('ok',false,'error','product_rate_or_provider_unit_budget_exceeded','http_status',429); END IF;
 INSERT INTO public.sandy_api_execution_admissions(actor_id,tenant_id,operation,request_id,is_mutation,input_sha256,contract_sha256,scope_sha256,registry_revision_sha256,declared_cost_units,expires_at) VALUES((principal->>'actor_id')::uuid,(principal->>'tenant_id')::uuid,p_operation,p_request_id,registry.is_mutation,input_hash,config->>'contract_sha256',scope_hash,public.sandy_api_registry_revision(p_operation),CASE WHEN (config->>'consumes_provider_units')::boolean THEN 1 ELSE 0 END,clock_timestamp()+interval '60 seconds') RETURNING * INTO admission;
 UPDATE public.sandy_api_rate_windows w SET requests=w.requests+1,declared_units=w.declared_units+admission.declared_cost_units WHERE w.actor_id=admission.actor_id AND w.bucket='product:'||admission.tenant_id::text AND w.window_start=active_window;
 PERFORM public.sandy_api_append_audit(admission.actor_id,p_operation,p_request_id,NULL,admission.id,'admission','admitted',input_hash,NULL,NULL,NULL);
 RETURN jsonb_build_object('ok',true,'allowed',true,'reused',false,'admission_id',admission.id,'grant_id',admission.grant_id,'request_id',p_request_id,'state','admitted','executed',false,'expires_at',admission.expires_at,'actor_id',admission.actor_id,'tenant_id',admission.tenant_id,'scope_sha256',scope_hash);
EXCEPTION WHEN data_exception THEN RETURN jsonb_build_object('ok',false,'error','invalid_product_arguments','http_status',400);
END $$;
CREATE FUNCTION public.sandy_product_consume(p_admission_id uuid,p_grant_id uuid,p_arguments jsonb,p_canonical_arguments text,p_channel text DEFAULT 'api') RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE admission public.sandy_api_execution_admissions%ROWTYPE;principal jsonb;config jsonb; proof jsonb;registry public.sandy_operation_registry%ROWTYPE;
BEGIN
 SELECT * INTO admission FROM public.sandy_api_execution_admissions WHERE id=p_admission_id FOR UPDATE;
 IF admission.id IS NULL OR admission.actor_id IS DISTINCT FROM auth.uid() OR auth.role() IS DISTINCT FROM 'authenticated' OR admission.grant_id IS DISTINCT FROM p_grant_id OR admission.credential_id IS NOT NULL THEN RETURN jsonb_build_object('ok',false,'error','product_grant_not_found','http_status',403); END IF;
 principal:=public.sandy_product_principal(admission.operation);SELECT contract INTO config FROM public.sandy_product_operation_contracts WHERE operation=admission.operation;
 SELECT * INTO registry FROM public.sandy_operation_registry WHERE operation=admission.operation;
 IF p_channel IS NULL OR p_channel NOT IN ('api','mcp') OR registry.handler IS DISTINCT FROM 'sandy-product-service-api' OR registry.api_exposed IS DISTINCT FROM true OR(p_channel='mcp' AND registry.ai_exposed IS DISTINCT FROM true) OR((registry.is_mutation OR(config->>'sensitive')::boolean) AND registry.verified IS DISTINCT FROM true) OR registry.error_contract->>'contract_sha256' IS DISTINCT FROM config->>'contract_sha256' OR registry.error_contract->>'requires_approval' IS DISTINCT FROM ((config->>'authorization'='owner') AND ((config->>'is_mutation')::boolean OR(config->>'sensitive')::boolean))::text OR registry.error_contract->>'api_key_delegable' IS DISTINCT FROM 'false' OR registry.input_schema IS DISTINCT FROM config->'input_schema' OR registry.output_schema IS DISTINCT FROM config->'output_schema' OR registry.permission_scope IS DISTINCT FROM (CASE WHEN config->>'authorization'='owner' THEN 'system:' ELSE 'product:' END||CASE WHEN (config->>'is_mutation')::boolean THEN 'write' ELSE 'read' END) THEN RETURN jsonb_build_object('ok',false,'error','product_contract_or_exposure_changed','http_status',409);END IF;
 IF principal IS NULL OR admission.actor_id IS DISTINCT FROM (principal->>'actor_id')::uuid OR admission.tenant_id IS DISTINCT FROM (principal->>'tenant_id')::uuid OR admission.state<>'admitted' OR admission.expires_at<=clock_timestamp() OR admission.input_sha256<>encode(extensions.digest(p_canonical_arguments,'sha256'),'hex') OR p_canonical_arguments::jsonb IS DISTINCT FROM p_arguments OR NOT public.sandy_product_input_valid(config->'input_schema',p_arguments) OR admission.scope_sha256<>public.sandy_product_scope_sha(admission.operation,admission.actor_id,admission.tenant_id,p_channel,admission.contract_sha256) OR admission.registry_revision_sha256 IS DISTINCT FROM public.sandy_api_registry_revision(admission.operation) THEN RETURN jsonb_build_object('ok',false,'error','product_grant_used_expired_or_changed','http_status',409); END IF;
 IF config->>'authorization'='owner' THEN
  proof:=public.sandy_api_consume_execution_grant(p_grant_id,admission.actor_id,NULL,admission.operation,admission.input_sha256,admission.request_id,admission.contract_sha256,admission.scope_sha256);
  IF proof->>'allowed' IS DISTINCT FROM 'true' THEN RETURN proof; END IF;
 ELSE
  UPDATE public.sandy_api_execution_admissions SET state='consumed',consumed_at=clock_timestamp() WHERE id=admission.id;
  PERFORM public.sandy_api_append_audit(admission.actor_id,admission.operation,admission.request_id,NULL,admission.id,'dispatch','consumed',admission.input_sha256,NULL,NULL,NULL);
 END IF;
 RETURN jsonb_build_object('ok',true,'admission_id',admission.id,'operation',admission.operation,'actor_id',admission.actor_id,'tenant_id',admission.tenant_id,'request_id',admission.request_id);
EXCEPTION WHEN data_exception THEN RETURN jsonb_build_object('ok',false,'error','invalid_product_arguments','http_status',400);
END $$;

