INSERT INTO public.sandy_product_operation_contracts VALUES ('commerce.invoice_forward.request','{"operation":"commerce.invoice_forward.request","contract_version":"1.0.0","executor":"legacy_invoice","authorization":"portal","is_mutation":true,"sensitive":true,"consumes_provider_units":true,"binding":"source_message","requirement_ids":[158],"input_schema":{"type":"object","properties":{"source_message_id":{"type":"string","format":"uuid"},"confirm_forward":{"const":true},"max_provider_units":{"const":1},"idempotency_key":{"type":"string","format":"uuid"}},"required":["source_message_id","confirm_forward","max_provider_units","idempotency_key"],"additionalProperties":false},"result_schema":{"type":"object"},"description":"commerce.invoice_forward.request: fixed scoped legacy_invoice service; submission, persisted state and independently verified delivery are distinct.","output_schema":{"type":"object","required":["ok","operation","contract_version","request_id","admission_id","request_state","executed","result","reconciliation_required"],"properties":{"ok":{"const":true},"operation":{"const":"commerce.invoice_forward.request"},"contract_version":{"const":"1.0.0"},"request_id":{"type":"string","format":"uuid"},"admission_id":{"type":"string","format":"uuid"},"request_state":{"enum":["observed","accepted","failed","unknown","replayed"]},"executed":{"type":["boolean","null"]},"result":{"type":"object","properties":{"item":{"anyOf":[{"type":"object","properties":{"id":{"type":"string","minLength":1,"maxLength":512},"state":{"type":"string","minLength":0,"maxLength":80},"status":{"type":"string","minLength":0,"maxLength":80},"display_name":{"type":"string","minLength":0,"maxLength":240},"subject":{"type":"string","minLength":0,"maxLength":1000},"created_at":{"anyOf":[{"type":"string","format":"date-time"},{"type":"null"}]},"updated_at":{"anyOf":[{"type":"string","format":"date-time"},{"type":"null"}]}},"additionalProperties":true},{"type":"null"}]},"items":{"type":"array","maxItems":100,"items":{"type":"object","properties":{"id":{"type":"string","minLength":1,"maxLength":512},"state":{"type":"string","minLength":0,"maxLength":80},"status":{"type":"string","minLength":0,"maxLength":80},"display_name":{"type":"string","minLength":0,"maxLength":240},"subject":{"type":"string","minLength":0,"maxLength":1000},"created_at":{"anyOf":[{"type":"string","format":"date-time"},{"type":"null"}]},"updated_at":{"anyOf":[{"type":"string","format":"date-time"},{"type":"null"}]}},"additionalProperties":true}},"changed":{"type":"boolean"},"next_cursor":{"type":["string","null"]},"possibly_truncated":{"type":"boolean"},"provider_id":{"type":["string","null"]},"provider_http_status":{"type":["integer","null"],"minimum":100,"maximum":599},"delivery_verified":{"type":"boolean"}},"required":["item","items","changed","next_cursor","possibly_truncated","provider_id","provider_http_status","delivery_verified"],"additionalProperties":false},"reconciliation_required":{"type":"boolean"}},"additionalProperties":false},"contract_sha256":"0a64bec44090dec1b7710022ab9de90c53c7a73c6f3867f044c82b6c2b2318b4"}'::jsonb);
INSERT INTO public.sandy_product_operation_contracts VALUES ('commerce.invoice_forward.receipt','{"operation":"commerce.invoice_forward.receipt","contract_version":"1.0.0","executor":"db","authorization":"portal","is_mutation":false,"sensitive":true,"consumes_provider_units":false,"binding":"none","requirement_ids":[158],"input_schema":{"type":"object","properties":{"source_message_id":{"type":"string","format":"uuid"}},"required":["source_message_id"],"additionalProperties":false},"result_schema":{"type":"object"},"description":"commerce.invoice_forward.receipt: fixed scoped db service; submission, persisted state and independently verified delivery are distinct.","output_schema":{"type":"object","required":["ok","operation","contract_version","request_id","admission_id","request_state","executed","result","reconciliation_required"],"properties":{"ok":{"const":true},"operation":{"const":"commerce.invoice_forward.receipt"},"contract_version":{"const":"1.0.0"},"request_id":{"type":"string","format":"uuid"},"admission_id":{"type":"string","format":"uuid"},"request_state":{"enum":["observed","accepted","failed","unknown","replayed"]},"executed":{"type":["boolean","null"]},"result":{"type":"object","properties":{"item":{"anyOf":[{"type":"object","properties":{"id":{"type":"string","minLength":1,"maxLength":512},"state":{"type":"string","minLength":0,"maxLength":80},"status":{"type":"string","minLength":0,"maxLength":80},"display_name":{"type":"string","minLength":0,"maxLength":240},"subject":{"type":"string","minLength":0,"maxLength":1000},"created_at":{"anyOf":[{"type":"string","format":"date-time"},{"type":"null"}]},"updated_at":{"anyOf":[{"type":"string","format":"date-time"},{"type":"null"}]}},"additionalProperties":true},{"type":"null"}]},"items":{"type":"array","maxItems":100,"items":{"type":"object","properties":{"id":{"type":"string","minLength":1,"maxLength":512},"state":{"type":"string","minLength":0,"maxLength":80},"status":{"type":"string","minLength":0,"maxLength":80},"display_name":{"type":"string","minLength":0,"maxLength":240},"subject":{"type":"string","minLength":0,"maxLength":1000},"created_at":{"anyOf":[{"type":"string","format":"date-time"},{"type":"null"}]},"updated_at":{"anyOf":[{"type":"string","format":"date-time"},{"type":"null"}]}},"additionalProperties":true}},"changed":{"type":"boolean"},"next_cursor":{"type":["string","null"]},"possibly_truncated":{"type":"boolean"},"provider_id":{"type":["string","null"]},"provider_http_status":{"type":["integer","null"],"minimum":100,"maximum":599},"delivery_verified":{"type":"boolean"}},"required":["item","items","changed","next_cursor","possibly_truncated","provider_id","provider_http_status","delivery_verified"],"additionalProperties":false},"reconciliation_required":{"type":"boolean"}},"additionalProperties":false},"contract_sha256":"e910c02658b8d29d9cb625f1349268610624fd72fe9a26817caf26c5015831e1"}'::jsonb);
INSERT INTO public.sandy_product_operation_contracts VALUES ('product.executions.get','{"operation":"product.executions.get","contract_version":"1.0.0","executor":"receipt","authorization":"authenticated","is_mutation":false,"sensitive":true,"consumes_provider_units":false,"binding":"none","requirement_ids":[144,159,161],"input_schema":{"type":"object","properties":{"request_id":{"type":"string","format":"uuid"}},"required":["request_id"],"additionalProperties":false},"result_schema":{"type":"object"},"description":"product.executions.get: fixed scoped receipt service; submission, persisted state and independently verified delivery are distinct.","output_schema":{"type":"object","required":["ok","operation","contract_version","request_id","admission_id","request_state","executed","result","reconciliation_required"],"properties":{"ok":{"const":true},"operation":{"const":"product.executions.get"},"contract_version":{"const":"1.0.0"},"request_id":{"type":"string","format":"uuid"},"admission_id":{"type":"string","format":"uuid"},"request_state":{"enum":["observed","accepted","failed","unknown","replayed"]},"executed":{"type":["boolean","null"]},"result":{"type":"object","properties":{"item":{"anyOf":[{"type":"object","properties":{"id":{"type":"string","minLength":1,"maxLength":512},"state":{"type":"string","minLength":0,"maxLength":80},"status":{"type":"string","minLength":0,"maxLength":80},"display_name":{"type":"string","minLength":0,"maxLength":240},"subject":{"type":"string","minLength":0,"maxLength":1000},"created_at":{"anyOf":[{"type":"string","format":"date-time"},{"type":"null"}]},"updated_at":{"anyOf":[{"type":"string","format":"date-time"},{"type":"null"}]}},"additionalProperties":true},{"type":"null"}]},"items":{"type":"array","maxItems":100,"items":{"type":"object","properties":{"id":{"type":"string","minLength":1,"maxLength":512},"state":{"type":"string","minLength":0,"maxLength":80},"status":{"type":"string","minLength":0,"maxLength":80},"display_name":{"type":"string","minLength":0,"maxLength":240},"subject":{"type":"string","minLength":0,"maxLength":1000},"created_at":{"anyOf":[{"type":"string","format":"date-time"},{"type":"null"}]},"updated_at":{"anyOf":[{"type":"string","format":"date-time"},{"type":"null"}]}},"additionalProperties":true}},"changed":{"type":"boolean"},"next_cursor":{"type":["string","null"]},"possibly_truncated":{"type":"boolean"},"provider_id":{"type":["string","null"]},"provider_http_status":{"type":["integer","null"],"minimum":100,"maximum":599},"delivery_verified":{"type":"boolean"}},"required":["item","items","changed","next_cursor","possibly_truncated","provider_id","provider_http_status","delivery_verified"],"additionalProperties":false},"reconciliation_required":{"type":"boolean"}},"additionalProperties":false},"contract_sha256":"5db5bbf19f83864daaa5edeabe2e403c3fef16d14df29acae773c2636c961af0"}'::jsonb);
