CREATE FUNCTION public.sandy_product_record_mutation(p_admission_id uuid,p_before jsonb,p_after jsonb) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE admission public.sandy_api_execution_admissions%ROWTYPE;hash text;
BEGIN
 SELECT * INTO admission FROM public.sandy_api_execution_admissions WHERE id=p_admission_id;
 IF admission.id IS NULL OR NOT admission.is_mutation OR admission.state<>'consumed' THEN RAISE EXCEPTION 'invalid_product_mutation_evidence';END IF;
 hash:=encode(extensions.digest(jsonb_build_object('before',p_before,'after',p_after)::text,'sha256'),'hex');
 INSERT INTO public.sandy_product_mutation_evidence VALUES(admission.id,p_before,p_after,hash,clock_timestamp());
 PERFORM public.sandy_api_append_audit(admission.actor_id,admission.operation,admission.request_id,NULL,admission.id,'mutation_state','recorded',admission.input_sha256,hash,NULL,NULL);
END $$;
CREATE FUNCTION public.sandy_product_result(p_item jsonb DEFAULT NULL,p_items jsonb DEFAULT '[]',p_changed boolean DEFAULT false,p_cursor text DEFAULT NULL,p_truncated boolean DEFAULT false) RETURNS jsonb
LANGUAGE sql IMMUTABLE SET search_path=pg_catalog,pg_temp AS $$ SELECT jsonb_build_object('item',p_item,'items',p_items,'changed',p_changed,'next_cursor',p_cursor,'possibly_truncated',p_truncated,'provider_id',NULL,'provider_http_status',NULL,'delivery_verified',false) $$;
CREATE FUNCTION public.sandy_product_execute_db(p_admission_id uuid,p_grant_id uuid,p_arguments jsonb,p_canonical_arguments text,p_channel text DEFAULT 'api') RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE proof jsonb;admission public.sandy_api_execution_admissions%ROWTYPE;op text;tenant uuid;actor uuid;item jsonb;items jsonb:='[]';result jsonb;before_row jsonb;after_row jsonb;snapshot uuid;case_row public.sandy_product_support_cases%ROWTYPE;count_limit integer:=coalesce((p_arguments->>'limit')::integer,50);changed boolean:=false;cursor text;compound jsonb;finish_state text;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.sandy_api_execution_admissions a JOIN public.sandy_product_operation_contracts c ON c.operation=a.operation WHERE a.id=p_admission_id AND c.contract->>'executor'='db') THEN RETURN jsonb_build_object('ok',false,'error','not_a_database_product_operation','http_status',400);END IF;
 proof:=public.sandy_product_consume(p_admission_id,p_grant_id,p_arguments,p_canonical_arguments,p_channel);IF proof->>'ok' IS DISTINCT FROM 'true' THEN RETURN proof;END IF;
 SELECT * INTO admission FROM public.sandy_api_execution_admissions WHERE id=p_admission_id;op:=admission.operation;tenant:=admission.tenant_id;actor:=admission.actor_id;
 IF op='customer.profile.get' THEN SELECT jsonb_build_object('id',id,'display_name',display_name,'created_at',created_at,'updated_at',updated_at) INTO item FROM public.email_customers WHERE id=tenant;
 ELSIF op='customer.profile.update' THEN SELECT jsonb_build_object('id',id,'display_name',display_name,'created_at',created_at,'updated_at',updated_at) INTO before_row FROM public.email_customers WHERE id=tenant FOR UPDATE; UPDATE public.email_customers SET display_name=btrim(p_arguments->>'display_name'),updated_at=clock_timestamp() WHERE id=tenant RETURNING jsonb_build_object('id',id,'display_name',display_name,'created_at',created_at,'updated_at',updated_at) INTO item;changed:=true;
 ELSIF op='customer.addresses.list' THEN SELECT coalesce(jsonb_agg(to_jsonb(q) ORDER BY q.id),'[]') INTO items FROM(SELECT id,email_address,is_primary,verified_at,created_at FROM public.email_customer_addresses WHERE customer_id=tenant AND(p_arguments->>'after_id' IS NULL OR id>(p_arguments->>'after_id')::uuid) ORDER BY id LIMIT count_limit)q;
 ELSIF op='support.cases.create' THEN INSERT INTO public.sandy_product_support_cases(customer_id,subject,details,category) VALUES(tenant,btrim(p_arguments->>'subject'),p_arguments->>'details',p_arguments->>'category') RETURNING to_jsonb(sandy_product_support_cases.*)-'customer_id' INTO item;changed:=true;
 ELSIF op='support.cases.list' THEN SELECT coalesce(jsonb_agg(to_jsonb(q)-'customer_id' ORDER BY q.id),'[]') INTO items FROM(SELECT * FROM public.sandy_product_support_cases WHERE customer_id=tenant AND(p_arguments->>'state' IS NULL OR state=p_arguments->>'state') AND(p_arguments->>'category' IS NULL OR category=p_arguments->>'category') AND(p_arguments->>'search' IS NULL OR position(lower(p_arguments->>'search') IN lower(subject))>0) AND (p_arguments->>'after_id' IS NULL OR id>(p_arguments->>'after_id')::uuid) ORDER BY id LIMIT count_limit)q;
 ELSIF op IN ('support.cases.get','support.cases.update','support.cases.close','support.cases.reopen','support.comments.list','support.comments.create') THEN
  SELECT * INTO case_row FROM public.sandy_product_support_cases WHERE id=(p_arguments->>'case_id')::uuid AND customer_id=tenant FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'product_resource_not_found' USING ERRCODE='P0404';END IF;
  before_row:=to_jsonb(case_row)-'customer_id';
  IF op IN ('support.cases.update','support.cases.close','support.cases.reopen') THEN
   IF case_row.version<>(p_arguments->>'expected_version')::integer THEN RAISE EXCEPTION 'product_resource_version_conflict' USING ERRCODE='P0409';END IF;
   UPDATE public.sandy_product_support_cases SET subject=CASE WHEN op='support.cases.update' THEN btrim(p_arguments->>'subject') ELSE subject END,details=CASE WHEN op='support.cases.update' THEN p_arguments->>'details' ELSE details END,state=CASE WHEN op='support.cases.close' THEN 'closed' WHEN op='support.cases.reopen' THEN 'open' ELSE state END,version=version+1,updated_at=clock_timestamp() WHERE id=case_row.id RETURNING to_jsonb(sandy_product_support_cases.*)-'customer_id' INTO item;changed:=true;
  ELSIF op='support.comments.create' THEN INSERT INTO public.sandy_product_support_comments(case_id,actor_id,body) VALUES(case_row.id,actor,p_arguments->>'body') RETURNING to_jsonb(sandy_product_support_comments.*)-'actor_id' INTO item;changed:=true;
  ELSIF op='support.comments.list' THEN SELECT coalesce(jsonb_agg(to_jsonb(q)-'actor_id' ORDER BY q.id),'[]') INTO items FROM(SELECT * FROM public.sandy_product_support_comments WHERE case_id=case_row.id AND (p_arguments->>'after_id' IS NULL OR id>(p_arguments->>'after_id')::uuid) ORDER BY id LIMIT count_limit)q;
  ELSE item:=to_jsonb(case_row)-'customer_id';END IF;
 ELSIF op IN ('notifications.preferences.get','notifications.preferences.update') THEN
  SELECT to_jsonb(p)-'customer_id' INTO before_row FROM public.sandy_product_notification_preferences p WHERE customer_id=tenant FOR UPDATE;
  IF op='notifications.preferences.update' THEN INSERT INTO public.sandy_product_notification_preferences(customer_id,email_enabled,whatsapp_enabled,file_alerts_enabled) VALUES(tenant,(p_arguments->>'email_enabled')::boolean,(p_arguments->>'whatsapp_enabled')::boolean,(p_arguments->>'file_alerts_enabled')::boolean) ON CONFLICT(customer_id) DO UPDATE SET email_enabled=excluded.email_enabled,whatsapp_enabled=excluded.whatsapp_enabled,file_alerts_enabled=excluded.file_alerts_enabled,updated_at=clock_timestamp();changed:=true;END IF;
  SELECT to_jsonb(p)-'customer_id' INTO item FROM public.sandy_product_notification_preferences p WHERE customer_id=tenant;
  IF item IS NULL THEN item:=jsonb_build_object('email_enabled',false,'whatsapp_enabled',false,'file_alerts_enabled',true,'updated_at',NULL);END IF;
 ELSIF op LIKE 'notifications.inbox.%' THEN
  SELECT to_jsonb(n)-'customer_id' INTO before_row FROM public.sandy_product_notification_inbox n WHERE id=(p_arguments->>'notification_id')::uuid AND customer_id=tenant FOR UPDATE;
  IF op='notifications.inbox.acknowledge' THEN UPDATE public.sandy_product_notification_inbox SET acknowledged_at=coalesce(acknowledged_at,clock_timestamp()) WHERE id=(p_arguments->>'notification_id')::uuid AND customer_id=tenant;changed:=FOUND;END IF;
  SELECT coalesce(jsonb_agg(to_jsonb(q)-'customer_id' ORDER BY q.id),'[]') INTO items FROM(SELECT * FROM public.sandy_product_notification_inbox WHERE customer_id=tenant AND(p_arguments->>'notification_id' IS NULL OR id=(p_arguments->>'notification_id')::uuid) AND(p_arguments->>'after_id' IS NULL OR id>(p_arguments->>'after_id')::uuid) ORDER BY id LIMIT count_limit)q;
  IF op<>'notifications.inbox.list' THEN item:=items->0;items:='[]';IF item IS NULL THEN RAISE EXCEPTION 'product_resource_not_found' USING ERRCODE='P0404';END IF;END IF;
 ELSIF op LIKE 'notifications.quiet_hours.%' THEN
  SELECT to_jsonb(q)-'customer_id' INTO before_row FROM public.sandy_product_notification_quiet_hours q WHERE customer_id=tenant FOR UPDATE;
  IF op='notifications.quiet_hours.update' THEN
   IF NOT EXISTS(SELECT 1 FROM pg_timezone_names WHERE name=p_arguments->>'timezone') OR p_arguments->>'start_minute'=p_arguments->>'end_minute' THEN RAISE EXCEPTION 'invalid_quiet_hours' USING ERRCODE='22023';END IF;
   INSERT INTO public.sandy_product_notification_quiet_hours(customer_id,enabled,timezone,start_minute,end_minute) VALUES(tenant,(p_arguments->>'enabled')::boolean,p_arguments->>'timezone',(p_arguments->>'start_minute')::integer,(p_arguments->>'end_minute')::integer) ON CONFLICT(customer_id) DO UPDATE SET enabled=excluded.enabled,timezone=excluded.timezone,start_minute=excluded.start_minute,end_minute=excluded.end_minute,updated_at=clock_timestamp();changed:=true;
  END IF;
  SELECT to_jsonb(q)-'customer_id' INTO item FROM public.sandy_product_notification_quiet_hours q WHERE customer_id=tenant;
  IF item IS NULL THEN item:=jsonb_build_object('enabled',false,'timezone','UTC','start_minute',1320,'end_minute',420,'updated_at',NULL);END IF;
 ELSIF op LIKE 'notifications.subscriptions.%' THEN
  SELECT to_jsonb(q)-'customer_id' INTO before_row FROM public.sandy_product_notification_subscriptions q WHERE customer_id=tenant AND topic=p_arguments->>'topic' FOR UPDATE;
  IF op='notifications.subscriptions.update' THEN INSERT INTO public.sandy_product_notification_subscriptions(customer_id,topic,enabled) VALUES(tenant,p_arguments->>'topic',(p_arguments->>'enabled')::boolean) ON CONFLICT(customer_id,topic) DO UPDATE SET enabled=excluded.enabled,updated_at=clock_timestamp();changed:=true;END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object('topic',t,'enabled',coalesce(n.enabled,true),'updated_at',n.updated_at) ORDER BY t),'[]') INTO items FROM unnest(ARRAY['support','file_alerts','improvements'])t LEFT JOIN public.sandy_product_notification_subscriptions n ON n.customer_id=tenant AND n.topic=t;
 ELSIF op LIKE 'notifications.templates.%' THEN
  SELECT to_jsonb(t) INTO before_row FROM public.sandy_product_notification_templates t WHERE id=(p_arguments->>'template_id')::uuid FOR UPDATE;
  IF op='notifications.templates.create' THEN INSERT INTO public.sandy_product_notification_templates(name,body_text) VALUES(p_arguments->>'name',p_arguments->>'body_text') RETURNING to_jsonb(sandy_product_notification_templates.*) INTO item;changed:=true;
  ELSIF op IN ('notifications.templates.update','notifications.templates.delete') THEN UPDATE public.sandy_product_notification_templates SET body_text=coalesce(p_arguments->>'body_text',body_text),deleted_at=CASE WHEN op='notifications.templates.delete' THEN clock_timestamp() ELSE NULL END,version=version+1,updated_at=clock_timestamp() WHERE id=(p_arguments->>'template_id')::uuid AND version=(p_arguments->>'expected_version')::integer AND deleted_at IS NULL RETURNING to_jsonb(sandy_product_notification_templates.*) INTO item;IF item IS NULL THEN RAISE EXCEPTION 'product_resource_version_conflict' USING ERRCODE='P0409';END IF;changed:=true;
  ELSE SELECT coalesce(jsonb_agg(to_jsonb(q) ORDER BY q.id),'[]') INTO items FROM(SELECT * FROM public.sandy_product_notification_templates WHERE deleted_at IS NULL AND(p_arguments->>'template_id' IS NULL OR id=(p_arguments->>'template_id')::uuid) AND(p_arguments->>'after_id' IS NULL OR id>(p_arguments->>'after_id')::uuid) ORDER BY id LIMIT count_limit)q;IF op='notifications.templates.get' THEN item:=items->0;items:='[]';IF item IS NULL THEN RAISE EXCEPTION 'product_resource_not_found' USING ERRCODE='P0404';END IF;END IF;END IF;
 ELSIF op LIKE 'product.configuration.snapshots.%' THEN
  SELECT coalesce(jsonb_agg(to_jsonb(q)-'admission_id' ORDER BY q.id),'[]') INTO items FROM(SELECT * FROM public.sandy_product_configuration_snapshots WHERE(p_arguments->>'snapshot_id' IS NULL OR id=(p_arguments->>'snapshot_id')::uuid) AND(p_arguments->>'after_id' IS NULL OR id>(p_arguments->>'after_id')::uuid) ORDER BY id LIMIT count_limit)q;
  IF op='product.configuration.snapshots.get' THEN item:=items->0;items:='[]';IF item IS NULL THEN RAISE EXCEPTION 'product_resource_not_found' USING ERRCODE='P0404';END IF;END IF;
 ELSIF op LIKE 'notifications.file_alerts.%' THEN
  IF op='notifications.file_alerts.list' THEN
   IF p_arguments ? 'cursor' THEN compound:=convert_from(decode(p_arguments->>'cursor','base64'),'UTF8')::jsonb;IF jsonb_typeof(compound)<>'object' OR (SELECT count(*) FROM jsonb_object_keys(compound))<>2 OR NOT compound ? 'file_id' OR NOT compound ? 'process' THEN RAISE EXCEPTION 'invalid_cursor' USING ERRCODE='22023';END IF;END IF;
   SELECT coalesce(jsonb_agg(to_jsonb(q)-'owner_customer_id' ORDER BY q.file_id,q.process),'[]') INTO items FROM(SELECT * FROM public.sandy_file_processing_alerts WHERE owner_customer_id=tenant AND(p_arguments->>'severity' IS NULL OR severity=p_arguments->>'severity') AND(p_arguments->>'resolved' IS NULL OR(resolved_at IS NOT NULL)=(p_arguments->>'resolved')::boolean) AND(compound IS NULL OR (file_id,process)>((compound->>'file_id')::uuid,compound->>'process')) ORDER BY file_id,process LIMIT count_limit)q;
   IF jsonb_array_length(items)=count_limit THEN cursor:=replace(encode(convert_to(jsonb_build_object('file_id',items->-1->>'file_id','process',items->-1->>'process')::text,'UTF8'),'base64'),E'\n','');END IF;
  ELSE
   SELECT to_jsonb(a)-'owner_customer_id' INTO before_row FROM public.sandy_file_processing_alerts a WHERE owner_customer_id=tenant AND file_id=(p_arguments->>'file_id')::uuid AND process=p_arguments->>'process' FOR UPDATE;
   IF op IN ('notifications.file_alerts.resolve','notifications.file_alerts.reopen') THEN UPDATE public.sandy_file_processing_alerts SET resolved_at=CASE WHEN op='notifications.file_alerts.resolve' THEN clock_timestamp() ELSE NULL END WHERE owner_customer_id=tenant AND file_id=(p_arguments->>'file_id')::uuid AND process=p_arguments->>'process';changed:=FOUND;END IF;
   SELECT to_jsonb(a)-'owner_customer_id' INTO item FROM public.sandy_file_processing_alerts a WHERE owner_customer_id=tenant AND file_id=(p_arguments->>'file_id')::uuid AND process=p_arguments->>'process';IF item IS NULL THEN RAISE EXCEPTION 'product_resource_not_found' USING ERRCODE='P0404';END IF;
  END IF;
 ELSIF op LIKE 'notifications.improvements.%' THEN
  SELECT coalesce(jsonb_agg(to_jsonb(q) ORDER BY q.id),'[]') INTO items FROM(SELECT n.id,n.request_id,n.notice_kind,n.state,n.delivery_channel,n.message,n.created_at,n.sent_at FROM public.sandy_improvement_notifications n JOIN public.sandy_improvement_requests r ON r.id=n.request_id WHERE r.requester_customer_id=tenant AND(p_arguments->>'notification_id' IS NULL OR n.id=(p_arguments->>'notification_id')::uuid) AND(p_arguments->>'after_id' IS NULL OR n.id>(p_arguments->>'after_id')::uuid) ORDER BY n.id LIMIT count_limit)q;IF op LIKE '%.get' THEN item:=items->0;items:='[]';IF item IS NULL THEN RAISE EXCEPTION 'product_resource_not_found' USING ERRCODE='P0404';END IF;END IF;
 ELSIF op LIKE 'product.configuration.providers.%' THEN
  IF op='product.configuration.providers.list' THEN SELECT coalesce(jsonb_agg(to_jsonb(p) ORDER BY p.provider_key),'[]') INTO items FROM public.email_ai_provider_config p;
  ELSIF op='product.configuration.providers.get' THEN SELECT to_jsonb(p) INTO item FROM public.email_ai_provider_config p WHERE p.provider_key=p_arguments->>'provider_key';
  ELSE
   IF op='product.configuration.providers.restore' THEN SELECT s.before_row INTO before_row FROM public.sandy_product_configuration_snapshots s WHERE s.id=(p_arguments->>'snapshot_id')::uuid;IF before_row IS NULL THEN RAISE EXCEPTION 'product_resource_not_found' USING ERRCODE='P0404';END IF;ELSE before_row:=p_arguments;END IF;
   SELECT to_jsonb(p) INTO after_row FROM public.email_ai_provider_config p WHERE p.provider_key=before_row->>'provider_key' FOR UPDATE;
   IF after_row IS NULL THEN RAISE EXCEPTION 'product_resource_not_found' USING ERRCODE='P0404';END IF;
   IF (after_row->>'updated_at')::timestamptz<>(p_arguments->>'expected_updated_at')::timestamptz THEN RAISE EXCEPTION 'product_resource_version_conflict' USING ERRCODE='P0409';END IF;
   IF (before_row->>'is_default')::boolean AND EXISTS(SELECT 1 FROM public.email_ai_provider_config WHERE is_default AND provider_key<>before_row->>'provider_key') THEN RAISE EXCEPTION 'product_default_provider_conflict' USING ERRCODE='P0409';END IF;
   UPDATE public.email_ai_provider_config SET model_name=before_row->>'model_name',enabled=(before_row->>'enabled')::boolean,is_default=(before_row->>'is_default')::boolean,updated_at=clock_timestamp() WHERE provider_key=before_row->>'provider_key' RETURNING to_jsonb(email_ai_provider_config.*) INTO item;
   INSERT INTO public.sandy_product_configuration_snapshots(admission_id,provider_key,before_row,after_row) VALUES(admission.id,item->>'provider_key',after_row,item) RETURNING id INTO snapshot;changed:=true;
  END IF;
 ELSIF op='graph.messages.list' THEN SELECT coalesce(jsonb_agg(to_jsonb(q) ORDER BY q.id),'[]') INTO items FROM(SELECT id,direction,subject,sender_address,received_at,sent_at,created_at,delivery_status FROM public.email_messages WHERE customer_id=tenant AND(p_arguments->>'after_id' IS NULL OR id>(p_arguments->>'after_id')::uuid) AND(p_arguments->>'direction' IS NULL OR direction=p_arguments->>'direction') AND(p_arguments->>'search' IS NULL OR position(lower(p_arguments->>'search') IN lower(coalesce(subject,'')))>0) ORDER BY id LIMIT count_limit)q;
 ELSIF op='graph.attachments.list' THEN SELECT coalesce(jsonb_agg(to_jsonb(q) ORDER BY q.id),'[]') INTO items FROM(SELECT a.id,a.filename,a.content_type,a.byte_size,a.direction,a.created_at FROM public.email_ai_attachments a JOIN public.email_messages m ON m.id=a.message_id WHERE m.customer_id=tenant AND m.id=(p_arguments->>'message_id')::uuid AND(p_arguments->>'after_id' IS NULL OR a.id>(p_arguments->>'after_id')::uuid) ORDER BY a.id LIMIT count_limit)q;
 ELSIF op='commerce.invoice_forward.receipt' THEN SELECT coalesce(jsonb_agg(to_jsonb(q) ORDER BY q.id),'[]') INTO items FROM(SELECT r.id,r.status,r.provider_message_id,r.created_at,r.updated_at FROM public.sandy_email_action_receipts r JOIN public.email_messages m ON m.id=r.source_message_id WHERE m.customer_id=tenant AND m.id=(p_arguments->>'source_message_id')::uuid AND r.action_type='invoice_forward' ORDER BY r.id LIMIT 100)q;
 ELSIF op LIKE 'whatsapp.messages.%' THEN
  SELECT coalesce(jsonb_agg(to_jsonb(q) ORDER BY q.id::bigint),'[]') INTO items FROM(SELECT m.id::text AS id,m.meta_message_id,m.direction,m.message_type,m.body,m.processing_status,m.created_at FROM public.sandy_whatsapp_messages m WHERE m.phone_number_id='1360367063825981' AND EXISTS(SELECT 1 FROM public.sandy_whatsapp_identities i WHERE i.wa_id=m.sender_wa_id AND i.customer_id=tenant AND i.verification_status='verified') AND(p_arguments->>'id' IS NULL OR m.id=(p_arguments->>'id')::bigint) AND(p_arguments->>'after_id' IS NULL OR m.id>(p_arguments->>'after_id')::bigint) ORDER BY m.id LIMIT count_limit)q;
  IF op LIKE '%.get' THEN item:=items->0;items:='[]';IF item IS NULL THEN RAISE EXCEPTION 'product_resource_not_found' USING ERRCODE='P0404';END IF;END IF;
 ELSIF op='whatsapp.identities.list' THEN SELECT coalesce(jsonb_agg(to_jsonb(q) ORDER BY q.wa_id),'[]') INTO items FROM(SELECT wa_id,verification_status,verified_at,allowed_scopes,is_primary FROM public.sandy_whatsapp_identities WHERE customer_id=tenant AND(p_arguments->>'after_wa_id' IS NULL OR wa_id>p_arguments->>'after_wa_id') ORDER BY wa_id LIMIT count_limit)q;IF jsonb_array_length(items)=count_limit THEN cursor:=items->-1->>'wa_id';END IF;
 ELSIF op LIKE 'whatsapp.topics.%' THEN SELECT coalesce(jsonb_agg(to_jsonb(q) ORDER BY q.id),'[]') INTO items FROM(SELECT id,title,summary,created_at,updated_at FROM public.sandy_whatsapp_topics WHERE customer_id=tenant AND(p_arguments->>'id' IS NULL OR id=(p_arguments->>'id')::uuid) AND(p_arguments->>'after_id' IS NULL OR id>(p_arguments->>'after_id')::uuid) ORDER BY id LIMIT count_limit)q;IF op LIKE '%.get' THEN item:=items->0;items:='[]';IF item IS NULL THEN RAISE EXCEPTION 'product_resource_not_found' USING ERRCODE='P0404';END IF;END IF;
 ELSIF op LIKE 'whatsapp.requests.%' THEN SELECT coalesce(jsonb_agg(to_jsonb(q) ORDER BY q.id),'[]') INTO items FROM(SELECT id,status,requested_wa_id,resolved_wa_id,meta_message_id,error_code,created_at,updated_at FROM public.sandy_whatsapp_outbound_requests WHERE customer_id=tenant AND(p_arguments->>'id' IS NULL OR id=(p_arguments->>'id')::uuid) AND(p_arguments->>'after_id' IS NULL OR id>(p_arguments->>'after_id')::uuid) ORDER BY id LIMIT count_limit)q;IF op LIKE '%.get' THEN item:=items->0;items:='[]';IF item IS NULL THEN RAISE EXCEPTION 'product_resource_not_found' USING ERRCODE='P0404';END IF;END IF;
 ELSE RAISE EXCEPTION 'not_a_database_product_operation' USING ERRCODE='22023';END IF;
 IF item IS NULL AND jsonb_array_length(items)=0 AND op IN ('customer.profile.get','customer.profile.update','product.configuration.providers.get') THEN RAISE EXCEPTION 'product_resource_not_found' USING ERRCODE='P0404';END IF;
 IF cursor IS NULL AND jsonb_array_length(items)=count_limit AND items->-1 ? 'id' THEN cursor:=items->-1->>'id';END IF;
 IF changed AND op LIKE 'support.%' AND coalesce((SELECT enabled FROM public.sandy_product_notification_subscriptions WHERE customer_id=tenant AND topic='support'),true) THEN INSERT INTO public.sandy_product_notification_inbox(customer_id,topic,event,resource_id) VALUES(tenant,'support',op,(item->>'id')::uuid);END IF;
 result:=public.sandy_product_result(item,items,changed,cursor,jsonb_array_length(items)>=count_limit);
 IF snapshot IS NOT NULL THEN result:=jsonb_set(result,'{item,snapshot_id}',to_jsonb(snapshot),true);END IF;
 IF admission.is_mutation THEN PERFORM public.sandy_product_record_mutation(admission.id,CASE WHEN op LIKE 'product.configuration.providers.%' THEN after_row WHEN op='support.comments.create' THEN NULL ELSE before_row END,CASE WHEN item IS NOT NULL THEN item ELSE items END);END IF;
 finish_state:=CASE WHEN admission.is_mutation THEN 'accepted' ELSE 'succeeded' END;
 proof:=public.sandy_api_finish_execution(admission.id,finish_state,200,NULL,encode(extensions.digest(result::text,'sha256'),'hex'));
 IF proof->>'ok' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'product_receipt_not_persisted' USING ERRCODE='P0503';END IF;
 INSERT INTO public.sandy_product_results(admission_id,result,created_at,executed) VALUES(admission.id,result,clock_timestamp(),true);
 RETURN jsonb_build_object('ok',true,'admission_id',admission.id,'request_id',admission.request_id,'request_state',CASE WHEN admission.is_mutation THEN 'accepted' ELSE 'observed' END,'executed',true,'result',result,'reconciliation_required',admission.is_mutation);
EXCEPTION WHEN SQLSTATE 'P0404' THEN RETURN jsonb_build_object('ok',false,'error','product_resource_not_found','http_status',404);
 WHEN SQLSTATE 'P0409' THEN RETURN jsonb_build_object('ok',false,'error','product_resource_version_conflict','http_status',409);
 WHEN data_exception OR check_violation OR not_null_violation THEN RETURN jsonb_build_object('ok',false,'error','invalid_product_arguments','http_status',400);
END $$;

CREATE TABLE public.sandy_product_provider_dispatches(admission_id uuid PRIMARY KEY REFERENCES public.sandy_api_execution_admissions(id),context jsonb NOT NULL,arguments jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp());
ALTER TABLE public.sandy_product_provider_dispatches ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.sandy_product_provider_dispatches FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION public.sandy_product_send_allowed(p_customer uuid,p_channel text) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE enabled boolean;quiet public.sandy_product_notification_quiet_hours%ROWTYPE;local_minute integer;
BEGIN
 SELECT CASE p_channel WHEN 'email' THEN email_enabled WHEN 'whatsapp' THEN whatsapp_enabled ELSE false END INTO enabled FROM public.sandy_product_notification_preferences WHERE customer_id=p_customer;
 IF enabled IS DISTINCT FROM true THEN RETURN false;END IF;
 SELECT * INTO quiet FROM public.sandy_product_notification_quiet_hours WHERE customer_id=p_customer;
 IF quiet.enabled THEN
  local_minute:=extract(hour FROM clock_timestamp() AT TIME ZONE quiet.timezone)::integer*60+extract(minute FROM clock_timestamp() AT TIME ZONE quiet.timezone)::integer;
  IF quiet.start_minute<quiet.end_minute AND local_minute>=quiet.start_minute AND local_minute<quiet.end_minute OR quiet.start_minute>quiet.end_minute AND(local_minute>=quiet.start_minute OR local_minute<quiet.end_minute) THEN RETURN false;END IF;
 END IF;RETURN true;
END $$;
CREATE FUNCTION public.sandy_product_bind_provider(p_admission_id uuid,p_grant_id uuid,p_arguments jsonb,p_canonical_arguments text,p_channel text DEFAULT 'api') RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE proof jsonb;admission public.sandy_api_execution_admissions%ROWTYPE;config jsonb;context jsonb:='{}';source public.email_messages%ROWTYPE;attachment public.email_ai_attachments%ROWTYPE;draft public.sandy_product_graph_drafts%ROWTYPE;wa public.sandy_whatsapp_messages%ROWTYPE;recipient text;claim uuid;sync public.sandy_product_graph_syncs%ROWTYPE;media public.sandy_product_whatsapp_media%ROWTYPE;
BEGIN
 SELECT a.* INTO admission FROM public.sandy_api_execution_admissions a JOIN public.sandy_product_operation_contracts c ON c.operation=a.operation WHERE a.id=p_admission_id AND c.contract->>'executor' IN ('graph','whatsapp','legacy_invoice') FOR UPDATE OF a;
 IF admission.id IS NULL THEN RETURN jsonb_build_object('ok',false,'error','not_a_provider_product_operation','http_status',400);END IF;
 proof:=public.sandy_product_consume(p_admission_id,p_grant_id,p_arguments,p_canonical_arguments,p_channel);IF proof->>'ok' IS DISTINCT FROM 'true' THEN RETURN proof;END IF;
 SELECT contract INTO config FROM public.sandy_product_operation_contracts WHERE operation=admission.operation;
 IF config->>'binding' IN ('message','source_message','attachment') THEN
  IF config->>'binding'='attachment' THEN
   SELECT a.* INTO attachment FROM public.email_ai_attachments a JOIN public.email_messages m ON m.id=a.message_id WHERE a.id=(p_arguments->>'attachment_id')::uuid AND m.customer_id=admission.tenant_id;
   IF attachment.id IS NULL OR attachment.provider_attachment_id IS NULL THEN RAISE EXCEPTION 'product_resource_not_found' USING ERRCODE='P0404';END IF;
   SELECT * INTO source FROM public.email_messages WHERE id=attachment.message_id AND customer_id=admission.tenant_id;
  ELSE SELECT * INTO source FROM public.email_messages WHERE id=coalesce(p_arguments->>'message_id',p_arguments->>'source_message_id')::uuid AND customer_id=admission.tenant_id;END IF;
  IF source.id IS NULL OR source.provider_message_id IS NULL THEN RAISE EXCEPTION 'product_resource_not_found' USING ERRCODE='P0404';END IF;
  context:=jsonb_build_object('source_message_id',source.id,'provider_message_id',source.provider_message_id,'internet_message_id',source.internet_message_id,'recipient',source.sender_address,'subject',source.subject);
  IF attachment.id IS NOT NULL THEN context:=context||jsonb_build_object('provider_attachment_id',attachment.provider_attachment_id,'attachment_id',attachment.id,'filename',attachment.filename,'content_type',attachment.content_type,'byte_size',attachment.byte_size);END IF;
  IF admission.operation IN ('graph.drafts.reply_create','graph.drafts.reply_all_create') AND(source.direction NOT IN ('incoming','inbound') OR source.sender_address IS NULL OR source.sender_address !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$') THEN RAISE EXCEPTION 'reply_recipient_not_bound' USING ERRCODE='P0409';END IF;
 ELSIF config->>'binding'='draft' THEN
  SELECT * INTO draft FROM public.sandy_product_graph_drafts WHERE id=(p_arguments->>'draft_id')::uuid AND customer_id=admission.tenant_id FOR UPDATE;
  IF draft.id IS NULL OR draft.state='deleted' THEN RAISE EXCEPTION 'product_resource_not_found' USING ERRCODE='P0404';END IF;
  IF (config->>'is_mutation')::boolean AND draft.state<>'draft' THEN RAISE EXCEPTION 'draft_not_dispatchable' USING ERRCODE='P0409';END IF;
  IF admission.operation='graph.drafts.confirm_send' AND draft.version IS DISTINCT FROM (p_arguments->>'expected_version')::integer THEN RAISE EXCEPTION 'draft_review_version_changed' USING ERRCODE='P0409';END IF;
  context:=jsonb_build_object('draft_id',draft.id,'provider_message_id',draft.provider_id,'source_message_id',draft.source_message_id,'recipient',draft.recipient,'draft_state',draft.state,'recipients',draft.recipients,'version',draft.version);
  IF admission.operation='graph.drafts.confirm_send' THEN
   IF NOT public.sandy_product_send_allowed(admission.tenant_id,'email') THEN RAISE EXCEPTION 'send_preference_or_quiet_hours_denied' USING ERRCODE='P0409';END IF;
  END IF;
  IF (config->>'is_mutation')::boolean THEN UPDATE public.sandy_product_graph_drafts SET state=CASE WHEN admission.operation='graph.drafts.confirm_send' THEN 'sending' ELSE 'editing' END,version=version+1,updated_at=clock_timestamp() WHERE id=draft.id;END IF;
 ELSIF config->>'binding'='whatsapp_message' THEN
  SELECT m.* INTO wa FROM public.sandy_whatsapp_messages m WHERE m.id=(p_arguments->>'message_id')::bigint AND m.direction='inbound' AND m.phone_number_id='1360367063825981' AND EXISTS(SELECT 1 FROM public.sandy_whatsapp_identities i WHERE i.wa_id=m.sender_wa_id AND i.customer_id=admission.tenant_id AND i.verification_status='verified');
  IF wa.id IS NULL THEN RAISE EXCEPTION 'product_resource_not_found' USING ERRCODE='P0404';END IF;
  context:=jsonb_build_object('provider_message_id',wa.meta_message_id);
  IF admission.operation LIKE 'whatsapp.messages.media.%' THEN IF wa.message_type NOT IN ('image','document','audio','video','sticker') OR wa.payload->wa.message_type->>'id' IS NULL THEN RAISE EXCEPTION 'product_resource_not_found' USING ERRCODE='P0404';END IF;context:=context||jsonb_build_object('provider_media_id',wa.payload->wa.message_type->>'id');END IF;
 ELSIF config->>'binding'='whatsapp_media' THEN
  SELECT * INTO media FROM public.sandy_product_whatsapp_media WHERE id=(p_arguments->>'media_id')::uuid AND customer_id=admission.tenant_id;IF media.id IS NULL THEN RAISE EXCEPTION 'product_resource_not_found' USING ERRCODE='P0404';END IF;context:=jsonb_build_object('provider_media_id',media.provider_id,'media_id',media.id,'filename',media.filename,'content_type',media.content_type);
 ELSIF config->>'binding'='graph_sync' THEN
  SELECT * INTO sync FROM public.sandy_product_graph_syncs WHERE id=(p_arguments->>'sync_id')::uuid AND actor_id=admission.actor_id FOR UPDATE;IF sync.id IS NULL THEN RAISE EXCEPTION 'product_resource_not_found' USING ERRCODE='P0404';END IF;IF sync.version<>(p_arguments->>'expected_version')::integer OR sync.state NOT IN ('ready','complete') THEN RAISE EXCEPTION 'sync_not_dispatchable' USING ERRCODE='P0409';END IF;context:=jsonb_build_object('sync_id',sync.id,'next_url',sync.next_url,'version',sync.version);UPDATE public.sandy_product_graph_syncs SET state='dispatching',updated_at=clock_timestamp() WHERE id=sync.id;
 END IF;
 IF admission.operation IN ('graph.drafts.create','graph.drafts.forward_create') THEN
  SELECT a.normalized_email INTO recipient FROM public.email_customer_addresses a WHERE a.id=(p_arguments->>'recipient_address_id')::uuid AND a.customer_id=admission.tenant_id AND a.verified_at IS NOT NULL;
  IF recipient IS NULL THEN RAISE EXCEPTION 'verified_recipient_address_required' USING ERRCODE='P0409';END IF;
  context:=context||jsonb_build_object('recipient',recipient);
 END IF;
 IF admission.operation='graph.drafts.reply_all_create' THEN context:=context||jsonb_build_object('allowed_recipients',(SELECT coalesce(jsonb_agg(normalized_email),'[]') FROM public.email_customer_addresses WHERE customer_id=admission.tenant_id AND verified_at IS NOT NULL));END IF;
 IF admission.operation LIKE 'graph.subscriptions.%' THEN SELECT jsonb_build_object('subscription_id',subscription_id,'expiration_at',expiration_at,'resource',resource) INTO context FROM public.email_ai_graph_subscriptions WHERE mailbox='ai@email.com.au';context:=coalesce(context,'{}');END IF;
 IF admission.operation IN ('whatsapp.messages.send_text','whatsapp.templates.send') THEN
  IF NOT public.sandy_product_send_allowed(admission.tenant_id,'whatsapp') THEN RAISE EXCEPTION 'send_preference_or_quiet_hours_denied' USING ERRCODE='P0409';END IF;
  recipient:=public.sandy_whatsapp_resolve_recipient(admission.tenant_id,p_arguments->>'requested_wa_id');
  IF recipient IS NULL THEN RAISE EXCEPTION 'verified_recipient_required' USING ERRCODE='P0409';END IF;
  context:=context||jsonb_build_object('recipient',recipient);
  IF admission.operation='whatsapp.templates.send' THEN
   INSERT INTO public.sandy_whatsapp_outbound_requests(idempotency_key,customer_id,requested_wa_id,resolved_wa_id,message_text,status) VALUES('product:'||admission.actor_id::text||':'||admission.request_id::text,admission.tenant_id,p_arguments->>'requested_wa_id',recipient,'[approved_template:'||(p_arguments->>'template_name')||':'||(p_arguments->>'language_code')||']','claimed') RETURNING id INTO claim;
   context:=context||jsonb_build_object('outbound_request_id',claim);
  END IF;
 END IF;
 INSERT INTO public.sandy_product_provider_dispatches VALUES(admission.id,context,p_arguments,clock_timestamp());
 RETURN proof||jsonb_build_object('context',context);
EXCEPTION WHEN SQLSTATE 'P0404' THEN RETURN jsonb_build_object('ok',false,'error','product_resource_not_found','http_status',404);
 WHEN SQLSTATE 'P0409' THEN RETURN jsonb_build_object('ok',false,'error','product_resource_state_or_send_policy_conflict','http_status',409);
 WHEN data_exception OR unique_violation THEN RETURN jsonb_build_object('ok',false,'error','invalid_or_duplicate_product_dispatch','http_status',409);
END $$;
CREATE FUNCTION public.sandy_product_finish_provider(p_admission_id uuid,p_grant_id uuid,p_actor_id uuid,p_tenant_id uuid,p_result jsonb,p_outcome text,p_provider_http_status integer DEFAULT NULL,p_private_context jsonb DEFAULT '{}') RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE admission public.sandy_api_execution_admissions%ROWTYPE;dispatch public.sandy_product_provider_dispatches%ROWTYPE;result jsonb;proof jsonb;draft_id uuid;provider_id text;draft_state text;
BEGIN
 SELECT * INTO admission FROM public.sandy_api_execution_admissions WHERE id=p_admission_id FOR UPDATE;
 SELECT * INTO dispatch FROM public.sandy_product_provider_dispatches WHERE admission_id=p_admission_id;
 IF auth.role() IS DISTINCT FROM 'service_role' OR admission.id IS NULL OR admission.actor_id IS DISTINCT FROM p_actor_id OR admission.tenant_id IS DISTINCT FROM p_tenant_id OR admission.grant_id IS DISTINCT FROM p_grant_id OR admission.state<>'consumed' OR dispatch.admission_id IS NULL OR p_outcome NOT IN ('succeeded','accepted','failed','unknown') OR admission.is_mutation AND p_outcome='succeeded' OR octet_length(p_result::text)>500000 OR p_result IS NULL OR jsonb_typeof(p_result)<>'object' THEN RETURN jsonb_build_object('ok',false,'error','invalid_product_provider_receipt','http_status',409);END IF;
 result:=public.sandy_product_result()||p_result;provider_id:=nullif(result->>'provider_id','');
 IF p_private_context ? 'recipients' AND (jsonb_typeof(p_private_context->'recipients')<>'array' OR jsonb_array_length(p_private_context->'recipients') NOT BETWEEN 1 AND 21 OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(p_private_context->'recipients')r WHERE lower(r)<>lower(dispatch.context->>'recipient') AND NOT coalesce(dispatch.context->'allowed_recipients' ? lower(r),false))) THEN RAISE EXCEPTION 'product_draft_recipient_receipt_mismatch';END IF;
 IF admission.operation IN ('graph.drafts.reply_create','graph.drafts.create','graph.drafts.forward_create','graph.drafts.reply_all_create') AND p_outcome IN ('accepted','unknown') AND provider_id IS NOT NULL THEN
  INSERT INTO public.sandy_product_graph_drafts(customer_id,source_message_id,provider_id,recipient,recipients,state) VALUES(admission.tenant_id,(dispatch.context->>'source_message_id')::uuid,provider_id,dispatch.context->>'recipient',coalesce(p_private_context->'recipients',jsonb_build_array(dispatch.context->>'recipient')),CASE WHEN p_outcome='accepted' THEN 'draft' ELSE 'unknown' END) RETURNING id INTO draft_id;
  result:=jsonb_set(result,'{item}',(CASE WHEN jsonb_typeof(result->'item')='object' THEN result->'item' ELSE '{}'::jsonb END)||jsonb_build_object('id',draft_id,'state',CASE WHEN p_outcome='accepted' THEN 'draft' ELSE 'unknown' END,'version',1),true);
 ELSIF admission.operation LIKE 'graph.drafts.%' AND dispatch.context ? 'draft_id' THEN
  draft_state:=CASE WHEN admission.operation='graph.drafts.confirm_send' THEN CASE WHEN p_outcome='accepted' THEN 'submitted' WHEN p_outcome='failed' THEN 'draft' ELSE 'unknown' END WHEN admission.operation='graph.drafts.delete' AND p_outcome='accepted' THEN 'deleted' WHEN admission.operation='graph.drafts.verify_sent' AND result->'item'->>'sent_confirmed'='true' THEN 'sent' WHEN admission.is_mutation THEN CASE WHEN p_outcome IN ('accepted','failed') THEN 'draft' ELSE 'unknown' END END;
  UPDATE public.sandy_product_graph_drafts SET state=coalesce(draft_state,sandy_product_graph_drafts.state),version=version+CASE WHEN admission.is_mutation THEN 1 ELSE 0 END,updated_at=clock_timestamp() WHERE id=(dispatch.context->>'draft_id')::uuid AND customer_id=admission.tenant_id;
 END IF;
 IF admission.operation LIKE 'graph.delta.%' THEN
  IF p_outcome='accepted' AND p_private_context->>'next_url' IS NOT NULL THEN
   IF p_private_context->>'next_url' !~ '^https://graph\.microsoft\.com/v1\.0/users/' THEN RAISE EXCEPTION 'invalid_graph_sync_receipt';END IF;
   IF admission.operation='graph.delta.start' THEN INSERT INTO public.sandy_product_graph_syncs(actor_id,next_url,state) VALUES(admission.actor_id,p_private_context->>'next_url',CASE WHEN p_private_context->>'complete'='true' THEN 'complete' ELSE 'ready' END) RETURNING id INTO draft_id;
   ELSE UPDATE public.sandy_product_graph_syncs SET next_url=p_private_context->>'next_url',state=CASE WHEN p_private_context->>'complete'='true' THEN 'complete' ELSE 'ready' END,version=version+1,updated_at=clock_timestamp() WHERE id=(dispatch.context->>'sync_id')::uuid AND actor_id=admission.actor_id RETURNING id INTO draft_id;END IF;
   result:=jsonb_set(result,'{item}',jsonb_build_object('id',draft_id,'state',CASE WHEN p_private_context->>'complete'='true' THEN 'complete' ELSE 'ready' END,'version',coalesce((dispatch.context->>'version')::integer,0)+1),true);
  ELSIF dispatch.context ? 'sync_id' THEN UPDATE public.sandy_product_graph_syncs SET state='unknown',updated_at=clock_timestamp() WHERE id=(dispatch.context->>'sync_id')::uuid AND actor_id=admission.actor_id;END IF;
 END IF;
 IF admission.operation='whatsapp.media.upload' AND p_outcome='accepted' AND provider_id IS NOT NULL THEN
  INSERT INTO public.sandy_product_whatsapp_media(customer_id,provider_id,filename,content_type) VALUES(admission.tenant_id,provider_id,dispatch.arguments->>'filename',dispatch.arguments->>'content_type') RETURNING id INTO draft_id;result:=jsonb_set(result,'{item}',jsonb_build_object('id',draft_id,'filename',dispatch.arguments->>'filename','content_type',dispatch.arguments->>'content_type'),true);
 END IF;
 IF admission.operation='graph.subscriptions.ensure' AND p_outcome='accepted' THEN
  IF p_result->'item'->>'id' IS NULL OR p_result->'item'->>'resource' IS DISTINCT FROM 'users/ai@email.com.au/mailFolders(''Inbox'')/messages' THEN RAISE EXCEPTION 'invalid_graph_subscription_receipt';END IF;
  INSERT INTO public.email_ai_graph_subscriptions(mailbox,subscription_id,expiration_at,resource,client_state,updated_at) VALUES('ai@email.com.au',p_result->'item'->>'id',(p_result->'item'->>'expirationDateTime')::timestamptz,p_result->'item'->>'resource',coalesce(p_private_context->>'client_state',(SELECT client_state FROM public.email_ai_graph_subscriptions WHERE mailbox='ai@email.com.au')),clock_timestamp()) ON CONFLICT(mailbox) DO UPDATE SET subscription_id=excluded.subscription_id,expiration_at=excluded.expiration_at,resource=excluded.resource,client_state=excluded.client_state,updated_at=clock_timestamp();
 ELSIF admission.operation='graph.subscriptions.delete' AND p_outcome='accepted' THEN DELETE FROM public.email_ai_graph_subscriptions WHERE mailbox='ai@email.com.au' AND subscription_id=dispatch.context->>'subscription_id';END IF;
 IF admission.operation='whatsapp.templates.send' AND dispatch.context ? 'outbound_request_id' THEN
  UPDATE public.sandy_whatsapp_outbound_requests SET status=CASE p_outcome WHEN 'accepted' THEN 'submitted' WHEN 'failed' THEN 'failed' ELSE 'unknown' END,meta_message_id=provider_id,error_code=CASE WHEN p_outcome='failed' THEN 'provider_rejected' WHEN p_outcome='unknown' THEN 'outcome_uncertain' END,updated_at=clock_timestamp() WHERE id=(dispatch.context->>'outbound_request_id')::uuid AND customer_id=admission.tenant_id;
  IF p_outcome='accepted' AND provider_id IS NOT NULL THEN INSERT INTO public.sandy_whatsapp_messages(meta_message_id,phone_number_id,sender_wa_id,direction,message_type,body,payload,processing_status) VALUES(provider_id,'1360367063825981',dispatch.context->>'recipient','outbound','template','[approved_template:'||(dispatch.arguments->>'template_name')||']',jsonb_build_object('source','sandy_product_service','request_id',dispatch.context->>'outbound_request_id'),'submitted') ON CONFLICT(meta_message_id) DO NOTHING;END IF;
 END IF;
 IF admission.is_mutation THEN PERFORM public.sandy_product_record_mutation(admission.id,coalesce(p_private_context->'before_state',dispatch.context),jsonb_build_object('outcome',p_outcome,'provider_http_status',p_provider_http_status,'observed_result',result,'independent_postcondition_verified',false));END IF;
 proof:=public.sandy_api_finish_execution(admission.id,p_outcome,p_provider_http_status,provider_id,encode(extensions.digest(result::text,'sha256'),'hex'));
 IF proof->>'ok' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'product_receipt_not_persisted';END IF;
 INSERT INTO public.sandy_product_results(admission_id,result,created_at,executed) VALUES(admission.id,result,clock_timestamp(),CASE WHEN p_private_context ? 'execution_attempted' THEN (p_private_context->>'execution_attempted')::boolean WHEN p_outcome='unknown' THEN NULL ELSE true END);
 RETURN jsonb_build_object('ok',true,'admission_id',admission.id,'request_id',admission.request_id,'request_state',CASE p_outcome WHEN 'succeeded' THEN 'observed' ELSE p_outcome END,'executed',CASE WHEN p_private_context ? 'execution_attempted' THEN (p_private_context->>'execution_attempted')::boolean WHEN p_outcome='unknown' THEN NULL ELSE true END,'result',result,'reconciliation_required',admission.is_mutation OR p_outcome='unknown');
END $$;
CREATE FUNCTION public.sandy_product_get_receipt(p_request_id uuid,p_channel text DEFAULT 'api') RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE admission public.sandy_api_execution_admissions%ROWTYPE;principal jsonb;result jsonb;dispatched boolean;
BEGIN
 IF auth.uid() IS NULL OR auth.role() IS DISTINCT FROM 'authenticated' THEN RETURN jsonb_build_object('ok',false,'error','authenticated_customer_session_required','http_status',401);END IF;
 IF p_channel IS NULL OR p_channel NOT IN ('api','mcp') OR NOT EXISTS(SELECT 1 FROM public.sandy_operation_registry r JOIN public.sandy_product_operation_contracts c ON c.operation=r.operation WHERE r.operation='product.executions.get' AND r.error_contract->>'requires_approval'='false' AND r.error_contract->>'api_key_delegable'='false' AND r.handler='sandy-product-service-api' AND r.api_exposed AND(p_channel='api' OR r.ai_exposed) AND r.verified AND r.error_contract->>'contract_sha256'=c.contract->>'contract_sha256' AND r.input_schema=c.contract->'input_schema' AND r.output_schema=c.contract->'output_schema') THEN RETURN jsonb_build_object('ok',false,'error','product_receipt_not_enabled_or_verified','http_status',403);END IF;
 SELECT * INTO admission FROM public.sandy_api_execution_admissions WHERE actor_id=auth.uid() AND request_id=p_request_id AND operation IN(SELECT operation FROM public.sandy_product_operation_contracts);
 IF admission.id IS NULL THEN RETURN jsonb_build_object('ok',false,'error','product_execution_not_found','http_status',404);END IF;
 principal:=public.sandy_product_principal(admission.operation);
 IF principal IS NULL OR admission.tenant_id IS DISTINCT FROM (principal->>'tenant_id')::uuid THEN RETURN jsonb_build_object('ok',false,'error','product_identity_or_grant_required','http_status',403);END IF;
 SELECT r.result,r.executed INTO result,dispatched FROM public.sandy_product_results r WHERE r.admission_id=admission.id;
 RETURN jsonb_build_object('ok',true,'admission_id',admission.id,'request_id',admission.request_id,'request_state',CASE WHEN result IS NOT NULL THEN 'replayed' ELSE 'unknown' END,'executed',CASE WHEN admission.state IN ('admitted','rejected') THEN false WHEN admission.state IN ('accepted','succeeded','failed') THEN dispatched ELSE NULL END,'result',public.sandy_product_result(jsonb_build_object('operation',admission.operation,'state',admission.state,'result',result,'redispatch_permitted',false,'created_at',admission.created_at,'finished_at',admission.finished_at)),'reconciliation_required',admission.state IN ('consumed','unknown','accepted'));
END $$;


REVOKE ALL ON FUNCTION public.sandy_product_record_mutation(uuid,jsonb,jsonb),public.sandy_product_input_valid(jsonb,jsonb,integer),public.sandy_product_principal(text),public.sandy_product_scope_sha(text,uuid,uuid,text,text),public.sandy_product_admit(text,jsonb,text,uuid,text,uuid),public.sandy_product_consume(uuid,uuid,jsonb,text,text),public.sandy_product_result(jsonb,jsonb,boolean,text,boolean),public.sandy_product_execute_db(uuid,uuid,jsonb,text,text),public.sandy_product_send_allowed(uuid,text),public.sandy_product_bind_provider(uuid,uuid,jsonb,text,text),public.sandy_product_finish_provider(uuid,uuid,uuid,uuid,jsonb,text,integer,jsonb),public.sandy_product_get_receipt(uuid,text) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.sandy_product_admit(text,jsonb,text,uuid,text,uuid),public.sandy_product_execute_db(uuid,uuid,jsonb,text,text),public.sandy_product_bind_provider(uuid,uuid,jsonb,text,text),public.sandy_product_get_receipt(uuid,text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.sandy_product_finish_provider(uuid,uuid,uuid,uuid,jsonb,text,integer,jsonb) TO service_role;
COMMIT;
